-- CreateEnum
CREATE TYPE "Role" AS ENUM ('USER', 'ADMIN');
CREATE TYPE "Difficulty" AS ENUM ('BEGINNER', 'INTERMEDIATE', 'ADVANCED');
CREATE TYPE "ExplanationLength" AS ENUM ('SHORT', 'NORMAL', 'LONG');
CREATE TYPE "TeachingStyle" AS ENUM ('BEGINNER_FRIENDLY', 'BALANCED', 'TECHNICAL');
CREATE TYPE "Theme" AS ENUM ('SYSTEM', 'LIGHT', 'DARK');
CREATE TYPE "LessonStatus" AS ENUM ('GENERATING', 'READY', 'FAILED');
CREATE TYPE "GenerationStatus" AS ENUM ('STARTED', 'SUCCEEDED', 'FAILED');

CREATE TABLE "User" ("id" TEXT NOT NULL, "email" TEXT NOT NULL, "name" TEXT NOT NULL, "passwordHash" TEXT NOT NULL, "role" "Role" NOT NULL DEFAULT 'USER', "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL, CONSTRAINT "User_pkey" PRIMARY KEY ("id"));
CREATE TABLE "UserSettings" ("id" TEXT NOT NULL, "userId" TEXT NOT NULL, "timezone" TEXT NOT NULL DEFAULT 'UTC', "notificationTime" TEXT NOT NULL DEFAULT '08:00', "notificationsEnabled" BOOLEAN NOT NULL DEFAULT false, "onboardingCompleted" BOOLEAN NOT NULL DEFAULT false, "difficulty" "Difficulty" NOT NULL DEFAULT 'BEGINNER', "theme" "Theme" NOT NULL DEFAULT 'SYSTEM', CONSTRAINT "UserSettings_pkey" PRIMARY KEY ("id"));
CREATE TABLE "Session" ("id" TEXT NOT NULL, "tokenHash" TEXT NOT NULL, "userId" TEXT NOT NULL, "expiresAt" TIMESTAMP(3) NOT NULL, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "Session_pkey" PRIMARY KEY ("id"));
CREATE TABLE "LearningConfigVersion" ("id" TEXT NOT NULL, "version" INTEGER NOT NULL, "domain" TEXT NOT NULL, "guidance" TEXT NOT NULL, "emphasizedTopics" JSONB NOT NULL, "avoidedTopics" JSONB NOT NULL, "defaultDifficulty" "Difficulty" NOT NULL DEFAULT 'BEGINNER', "explanationLength" "ExplanationLength" NOT NULL DEFAULT 'NORMAL', "teachingStyle" "TeachingStyle" NOT NULL DEFAULT 'BEGINNER_FRIENDLY', "additionalGuidance" TEXT, "active" BOOLEAN NOT NULL DEFAULT false, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "createdById" TEXT, CONSTRAINT "LearningConfigVersion_pkey" PRIMARY KEY ("id"));
CREATE TABLE "DailyLesson" ("id" TEXT NOT NULL, "userId" TEXT NOT NULL, "localDate" TEXT NOT NULL, "status" "LessonStatus" NOT NULL DEFAULT 'GENERATING', "title" TEXT, "topicKey" TEXT, "difficulty" "Difficulty", "estimatedReadingMinutes" INTEGER, "introduction" TEXT, "concept" TEXT, "howItWorks" TEXT, "whyItMatters" TEXT, "concreteExample" TEXT, "keyTerms" JSONB, "quizQuestion" TEXT, "quizOptions" JSONB, "quizCorrectIndex" INTEGER, "quizExplanation" TEXT, "prerequisiteTopics" JSONB, "relatedTopics" JSONB, "learningConfigVersionId" TEXT, "aiModel" TEXT, "openedAt" TIMESTAMP(3), "notificationSentAt" TIMESTAMP(3), "generatedAt" TIMESTAMP(3), "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL, CONSTRAINT "DailyLesson_pkey" PRIMARY KEY ("id"));
CREATE TABLE "LessonCompletion" ("id" TEXT NOT NULL, "lessonId" TEXT NOT NULL, "userId" TEXT NOT NULL, "localDate" TEXT NOT NULL, "quizCorrect" BOOLEAN NOT NULL, "completedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "LessonCompletion_pkey" PRIMARY KEY ("id"));
CREATE TABLE "QuizAttempt" ("id" TEXT NOT NULL, "lessonId" TEXT NOT NULL, "userId" TEXT NOT NULL, "selectedIndex" INTEGER NOT NULL, "correct" BOOLEAN NOT NULL, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "QuizAttempt_pkey" PRIMARY KEY ("id"));
CREATE TABLE "UserTopicProgress" ("id" TEXT NOT NULL, "userId" TEXT NOT NULL, "topicKey" TEXT NOT NULL, "timesCompleted" INTEGER NOT NULL DEFAULT 0, "correctAnswers" INTEGER NOT NULL DEFAULT 0, "lastStudiedAt" TIMESTAMP(3) NOT NULL, CONSTRAINT "UserTopicProgress_pkey" PRIMARY KEY ("id"));
CREATE TABLE "PushSubscription" ("id" TEXT NOT NULL, "userId" TEXT NOT NULL, "endpoint" TEXT NOT NULL, "p256dh" TEXT NOT NULL, "auth" TEXT NOT NULL, "userAgent" TEXT, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL, CONSTRAINT "PushSubscription_pkey" PRIMARY KEY ("id"));
CREATE TABLE "AiGenerationLog" ("id" TEXT NOT NULL, "userId" TEXT, "lessonId" TEXT, "learningConfigVersionId" TEXT, "status" "GenerationStatus" NOT NULL, "model" TEXT NOT NULL, "durationMs" INTEGER, "inputTokens" INTEGER, "outputTokens" INTEGER, "errorCode" TEXT, "errorMessage" TEXT, "attempt" INTEGER NOT NULL DEFAULT 1, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "AiGenerationLog_pkey" PRIMARY KEY ("id"));
CREATE TABLE "RateLimit" ("key" TEXT NOT NULL, "count" INTEGER NOT NULL DEFAULT 1, "resetAt" TIMESTAMP(3) NOT NULL, "updatedAt" TIMESTAMP(3) NOT NULL, CONSTRAINT "RateLimit_pkey" PRIMARY KEY ("key"));

CREATE UNIQUE INDEX "User_email_key" ON "User"("email"); CREATE INDEX "User_createdAt_idx" ON "User"("createdAt");
CREATE UNIQUE INDEX "UserSettings_userId_key" ON "UserSettings"("userId");
CREATE UNIQUE INDEX "Session_tokenHash_key" ON "Session"("tokenHash"); CREATE INDEX "Session_userId_idx" ON "Session"("userId"); CREATE INDEX "Session_expiresAt_idx" ON "Session"("expiresAt");
CREATE UNIQUE INDEX "LearningConfigVersion_version_key" ON "LearningConfigVersion"("version"); CREATE INDEX "LearningConfigVersion_active_createdAt_idx" ON "LearningConfigVersion"("active", "createdAt");
CREATE UNIQUE INDEX "LearningConfigVersion_single_active_key" ON "LearningConfigVersion"((active)) WHERE active = true;
CREATE UNIQUE INDEX "DailyLesson_userId_localDate_key" ON "DailyLesson"("userId", "localDate"); CREATE INDEX "DailyLesson_userId_createdAt_idx" ON "DailyLesson"("userId", "createdAt"); CREATE INDEX "DailyLesson_status_localDate_idx" ON "DailyLesson"("status", "localDate"); CREATE INDEX "DailyLesson_topicKey_idx" ON "DailyLesson"("topicKey");
CREATE UNIQUE INDEX "LessonCompletion_lessonId_key" ON "LessonCompletion"("lessonId"); CREATE UNIQUE INDEX "LessonCompletion_userId_localDate_key" ON "LessonCompletion"("userId", "localDate"); CREATE INDEX "LessonCompletion_userId_completedAt_idx" ON "LessonCompletion"("userId", "completedAt");
CREATE UNIQUE INDEX "QuizAttempt_lessonId_userId_key" ON "QuizAttempt"("lessonId", "userId"); CREATE INDEX "QuizAttempt_userId_createdAt_idx" ON "QuizAttempt"("userId", "createdAt");
CREATE UNIQUE INDEX "UserTopicProgress_userId_topicKey_key" ON "UserTopicProgress"("userId", "topicKey"); CREATE INDEX "UserTopicProgress_userId_lastStudiedAt_idx" ON "UserTopicProgress"("userId", "lastStudiedAt");
CREATE UNIQUE INDEX "PushSubscription_endpoint_key" ON "PushSubscription"("endpoint"); CREATE INDEX "PushSubscription_userId_idx" ON "PushSubscription"("userId");
CREATE INDEX "AiGenerationLog_status_createdAt_idx" ON "AiGenerationLog"("status", "createdAt"); CREATE INDEX "AiGenerationLog_userId_createdAt_idx" ON "AiGenerationLog"("userId", "createdAt"); CREATE INDEX "RateLimit_resetAt_idx" ON "RateLimit"("resetAt");

ALTER TABLE "UserSettings" ADD CONSTRAINT "UserSettings_userId_fkey" FOREIGN KEY ("userId") REFERENCES "User"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "Session" ADD CONSTRAINT "Session_userId_fkey" FOREIGN KEY ("userId") REFERENCES "User"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "LearningConfigVersion" ADD CONSTRAINT "LearningConfigVersion_createdById_fkey" FOREIGN KEY ("createdById") REFERENCES "User"("id") ON DELETE SET NULL ON UPDATE CASCADE;
ALTER TABLE "DailyLesson" ADD CONSTRAINT "DailyLesson_userId_fkey" FOREIGN KEY ("userId") REFERENCES "User"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "DailyLesson" ADD CONSTRAINT "DailyLesson_learningConfigVersionId_fkey" FOREIGN KEY ("learningConfigVersionId") REFERENCES "LearningConfigVersion"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
ALTER TABLE "LessonCompletion" ADD CONSTRAINT "LessonCompletion_lessonId_fkey" FOREIGN KEY ("lessonId") REFERENCES "DailyLesson"("id") ON DELETE CASCADE ON UPDATE CASCADE; ALTER TABLE "LessonCompletion" ADD CONSTRAINT "LessonCompletion_userId_fkey" FOREIGN KEY ("userId") REFERENCES "User"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "QuizAttempt" ADD CONSTRAINT "QuizAttempt_lessonId_fkey" FOREIGN KEY ("lessonId") REFERENCES "DailyLesson"("id") ON DELETE CASCADE ON UPDATE CASCADE; ALTER TABLE "QuizAttempt" ADD CONSTRAINT "QuizAttempt_userId_fkey" FOREIGN KEY ("userId") REFERENCES "User"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "UserTopicProgress" ADD CONSTRAINT "UserTopicProgress_userId_fkey" FOREIGN KEY ("userId") REFERENCES "User"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "PushSubscription" ADD CONSTRAINT "PushSubscription_userId_fkey" FOREIGN KEY ("userId") REFERENCES "User"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "AiGenerationLog" ADD CONSTRAINT "AiGenerationLog_userId_fkey" FOREIGN KEY ("userId") REFERENCES "User"("id") ON DELETE SET NULL ON UPDATE CASCADE; ALTER TABLE "AiGenerationLog" ADD CONSTRAINT "AiGenerationLog_lessonId_fkey" FOREIGN KEY ("lessonId") REFERENCES "DailyLesson"("id") ON DELETE SET NULL ON UPDATE CASCADE; ALTER TABLE "AiGenerationLog" ADD CONSTRAINT "AiGenerationLog_learningConfigVersionId_fkey" FOREIGN KEY ("learningConfigVersionId") REFERENCES "LearningConfigVersion"("id") ON DELETE SET NULL ON UPDATE CASCADE;
